'use strict';
const app=document.querySelector('#app');
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(n/100);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={catalog:null,cart:new Map(),coupon:'',quote:null,affiliate:'',order:null,token:'',tab:'orders',admin:null,goaffproPreview:null,affiliateProfile:null,profileSlug:'',profileToken:'',customer:null,customerAdmin:null,points:0,migrationPreview:null,setupId:'',setupToken:'',orderSearch:'',orderStatus:'all',orderMode:'all',shoppingView:'store'};
let toastTimer;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.style.display='none',5000)}
async function api(path,data,token){const opts={headers:{}};if(data!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}if(token)opts.headers['X-Order-Token']=token;opts.headers['X-Store-Request']='1';const r=await fetch('/.netlify/functions/store-next?route='+encodeURIComponent(path.replace(/^\/api/,'')),opts);const result=await r.json();if(!r.ok)throw new Error(result.error||'Request failed');return result}
const button=(label,action,cls='')=>`<button type="button" data-action="${action}" class="${cls}">${label}</button>`;
function cartData(){return{items:Array.from(state.cart,([id,quantity])=>({id,quantity})),coupon:state.coupon,affiliate:state.affiliate,points_redeemed:state.points}}
async function calculate(){state.quote=state.cart.size?await api('/api/quote',cartData()):null;sessionStorage.setItem('glow_cart',JSON.stringify(cartData()))}
function totals(q){return `<div class="row"><span>Subtotal</span><span>${money(q.subtotal)}</span></div><div class="row"><span>Promo discount</span><span>−${money(q.coupon_discount??q.discount)}</span></div>${q.rewards_discount?`<div class="row"><span>Rewards (${q.points_redeemed} points)</span><span>−${money(q.rewards_discount)}</span></div>`:''}<div class="row"><span>Shipping</span><span>${money(q.shipping)}</span></div><div class="row"><span>Tax</span><span>${money(q.tax)}</span></div><div class="row total"><span>Total</span><span>${money(q.total)}</span></div>${q.affiliate_name?`<p class="muted">Affiliate credit: ${esc(q.affiliate_name)}${q.affiliate_source==='coupon'?' (coupon code)':''}</p>`:''}`}
async function loadStore(){const incomingCoupon=new URLSearchParams(location.search||'').get('coupon');if(incomingCoupon&&incomingCoupon.length<=40)state.coupon=incomingCoupon.trim();state.affiliate='';state.affiliateProfile=null;const emailed=location.hash?.match(/^#order=(GLP-[A-F0-9]{10})\.([A-Za-z0-9_-]{43})$/);if(emailed){history.replaceState(null,'',location.pathname);sessionStorage.setItem('glow_order',JSON.stringify({id:emailed[1],token:emailed[2]}))}state.catalog=await api('/api/catalog');renderMode(state.catalog.settings);try{state.customer=await api('/api/account')}catch{state.customer=null}const slug=decodeURIComponent(location.pathname.replace(/^\/store-next\/?/,'').replace(/\/$/,''));if(slug){try{state.affiliateProfile=await api('/api/storefronts/'+encodeURIComponent(slug));state.affiliate=state.affiliateProfile.slug;sessionStorage.setItem('glow_customer_store',state.affiliate);document.title=state.affiliateProfile.name+' · Glow GLP’s';document.querySelectorAll('header a[href="/store-next/"]').forEach(a=>a.setAttribute('href','/store-next/'+slug))}catch{app.innerHTML='<h1>Storefront unavailable</h1><a href="/store-next/">Visit the main store</a>';return}}if(!slug){const ref=new URLSearchParams(location.search||'').get('ref')||sessionStorage.getItem('glow_referral');const savedAffiliate=sessionStorage.getItem('glow_customer_store');if(ref||savedAffiliate){try{state.affiliateProfile=await api(ref?'/api/referrals/'+encodeURIComponent(ref):'/api/storefronts/'+encodeURIComponent(savedAffiliate));state.affiliate=state.affiliateProfile.slug;sessionStorage.setItem('glow_customer_store',state.affiliate);document.title=state.affiliateProfile.name+' · Glow GLP’s'}catch{sessionStorage.removeItem('glow_referral');sessionStorage.removeItem('glow_customer_store');toast('This affiliate link is unavailable. You can still shop in the main store.')}}}else{sessionStorage.removeItem('glow_referral')}const savedCart=sessionStorage.getItem('glow_cart');if(savedCart){try{const c=JSON.parse(savedCart);state.cart=new Map(c.items.filter(i=>Number.isInteger(i.id)&&Number.isInteger(i.quantity)&&i.quantity>0&&i.quantity<=100&&state.catalog.products.some(p=>p.id===i.id&&p.stock>=i.quantity)).map(i=>[i.id,i.quantity]));state.coupon=incomingCoupon&&incomingCoupon.length<=40?incomingCoupon.trim():typeof c.coupon==='string'?c.coupon:'';await calculate()}catch{state.cart.clear();state.coupon='';state.quote=null;sessionStorage.removeItem('glow_cart')}}const saved=sessionStorage.getItem('glow_order');if(saved){try{const d=JSON.parse(saved);state.order=await api('/api/orders/'+d.id,undefined,d.token);state.token=d.token;renderOrder();return}catch{sessionStorage.removeItem('glow_order')}}renderStore()}

function focusLegacyProduct(){const m=location.hash?.match(/^#product\/([a-z0-9-]+)$/);if(!m)return;const ids=new Set(state.catalog.products.filter(p=>p.slug===m[1]).map(p=>String(p.id)));if(!ids.size)return;document.querySelectorAll('#products .card').forEach(c=>c.hidden=!ids.has(c.dataset.productId))}
function updateBagButton(){const b=document.querySelector('[data-action="view-bag"]');if(!b)return;const count=Array.from(state.cart.values()).reduce((n,q)=>n+q,0);b.hidden=false;b.textContent='View bag ('+count+')'}
function renderStore(){state.shoppingView='store';updateBagButton();const a=state.affiliateProfile;app.innerHTML=`<section class="storefront-hero" aria-label="Glow Lab Protocols"><img class="hero-banner" src="/img/glow-banner-20261005.webp" alt="Glow Lab Protocols research vials with gold caps and a gold molecular structure" width="1717" height="916" fetchpriority="high"><div class="hero-brand"><img src="/img/glp-mark-8ae0a0b7.png" alt="GLP" width="105" height="91"><span>GLOW LAB</span><small>PROTOCOLS</small><a class="hero-shop" href="#collection">Shop the collection <span aria-hidden="true">↓</span></a></div></section><div class="storefront-content">${a?`<section class="affiliate affiliate-heading">${a.photo_url?`<img class="affiliate-avatar" src="${esc(a.photo_url)}" alt="${esc(a.name)}">`:`<div class="affiliate-avatar avatar-placeholder" aria-hidden="true">${esc(a.name.trim().charAt(0).toUpperCase())}</div>`}<div><div class="eyebrow">Shopping with your Glow affiliate</div><h2>${esc(a.name)}’s Glow GLP’s Store</h2>${a.bio?`<p class="muted">${esc(a.bio)}</p>`:''}</div></section>`:''}<section id="collection" class="collection"><div class="collection-heading"><div><div class="eyebrow">The research collection</div><h1>Explore Glow Lab.</h1></div><label class="search">Find a product<input id="search" type="search" placeholder="Search products"></label></div><div class="grid" id="products">${state.catalog.products.map(p=>`<article class="card" data-product-id="${p.id}" data-name="${esc(p.name.toLowerCase())}">${p.image?`<img class="product-image" src="${esc(p.image)}" alt="" loading="lazy">`:""}${p.additional_images?.length?`<details class="product-more-photos"><summary>More photos</summary>${p.additional_images.map(src=>`<img class="product-image" src="${esc(src)}" alt="${esc(p.name)} alternate view" loading="lazy">`).join('')}</details>`:''}<h3>${esc(p.name)}</h3><p class="stock">${p.stock?'In stock · '+p.stock+' available':'Out of stock'}</p><div class="bottom"><span class="price">${money(p.price)}</span><button data-action="add" data-id="${p.id}" ${p.stock===0?'disabled':''}>${p.stock?'Add to bag':'Out of stock'}</button></div></article>`).join('')}</div></section></div>`;focusLegacyProduct()}
function renderBag(){state.shoppingView='bag';updateBagButton();app.innerHTML=`<div class="intro"><div class="eyebrow">Your Glow Lab collection</div><h1>Your bag.</h1><p class="muted">Review your products, add a promo code and use your rewards before checkout.</p></div><div class="bag-layout"><section class="panel bag-panel"><h2>Your order</h2>${state.cart.size?Array.from(state.cart,([id,qty])=>{const p=state.catalog.products.find(p=>p.id===id);return `<div class="line"><strong>${esc(p.name)}</strong><div class="row"><div class="qty"><button data-action="minus" data-id="${id}" aria-label="Remove one ${esc(p.name)}">−</button><span>${qty}</span><button data-action="plus" data-id="${id}" aria-label="Add one ${esc(p.name)}">+</button></div><span>${money(p.price*qty)}</span></div></div>`}).join(''):'<p class="muted">Your cart is ready when you are.</p>'}<div class="inline"><label>Coupon code<input id="coupon" value="${esc(state.coupon)}" placeholder="Enter promo code"></label>${button('Apply','coupon','secondary')}</div>${rewardsCart()}${state.quote?totals(state.quote):''}<div class="notice">${state.catalog.settings.demo!==false?'Preview checkout · do not send money.':'Save your details, pay, then attach your screenshot and submit your order for payment verification.'}</div>${button('Continue to checkout','checkout','full')}<p><small>Shipping is calculated after discounts. Points can be used with one promo code.</small></p></section><div class="bag-help"><h2>A few things to know.</h2><p>Shipping is calculated after discounts. Rewards can be used with one promo code.</p><p>At checkout, save your details, pay using your chosen payment service, then upload your screenshot and submit your order.</p>${button('Continue shopping','browse-store','secondary')}</div></div>`}
function checkout(){if(!state.cart.size){toast('Add a product first.');return}const preview=state.catalog.settings.demo!==false,labels={venmo:'Venmo',paypal:'PayPal',cashapp:'Cash App',zelle:'Zelle'},methods=Object.entries(labels).filter(([k])=>preview||state.catalog.settings.payment_links?.[k]);if(!methods.length){toast('Payment recipients are not configured yet.');return}app.innerHTML=`<div class="intro"><div class="eyebrow">${preview?'Preview checkout':'Checkout'}</div><h1>Your details, then payment.</h1><p class="muted">${preview?'Use fictional customer details. Do not send money.':'Step 1 of 3: confirm your shipping address and choose how you’ll pay. Next, pay and upload your screenshot to submit your order.'} ${state.catalog.settings.email_enabled?'A private return link will be emailed when your checkout draft is saved. Keep this page open while you pay.':'Keep this checkout page open; automatic return emails are not enabled.'}</p></div><div class="layout"><form id="checkout" class="panel"><h2>Shipping details · United States</h2><div class="fields">${[['name','Full name','text','name'],['email','Email','email','email'],['phone','Phone number (for order questions)','tel','tel'],['address','Street address, including apartment or unit','text','shipping street-address'],['city','City','text','shipping address-level2'],['state','State / territory · two-letter code','text','shipping address-level1'],['zip','ZIP code','text','shipping postal-code']].map(([k,label,type,autocomplete])=>`<label class="${k==='address'?'wide':''}">${label}<input name="${k}" type="${type}" required maxlength="${k==='address'?500:k==='state'?2:k==='zip'?10:k==='phone'?32:150}" autocomplete="${autocomplete}" ${k==='state'?'pattern="[A-Za-z]{2}"':k==='zip'?'pattern="[0-9]{5}(-[0-9]{4})?"':''} value="${esc(k==='email'?state.customer?.customer.email||'':k==='name'?state.customer?.customer.name||'':'')}" ${k==='email'&&state.customer?'readonly':''}></label>`).join('')}<label class="wide">Payment method<select name="payment_method">${methods.map(([k,label])=>`<option value="${k}">${label}</option>`).join('')}</select></label></div><div class="notice">Continuing saves a draft and reserves stock and any rewards for 24 hours. Your order is submitted only when you upload a screenshot. Staff then verify the actual payment.${preview?' This is a preview; do not send money.':''}</div><p id="checkout-error" class="error" role="alert"></p><div class="actions"><button type="submit">${preview?'Continue to test payment':'Continue to payment'}</button>${button('Back to cart','back','secondary')}</div></form><aside class="panel"><h2>Order summary</h2>${state.quote.items.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.quantity}</span><span>${money(i.amount)}</span></div>`).join('')}${totals(state.quote)}${state.affiliate?`<p class="muted">Affiliate: ${esc(state.affiliate)}</p>`:''}</aside></div>`;document.querySelector('#checkout').dataset.key=crypto.randomUUID()}
function renderMode(settings){const preview=settings.demo!==false;const banner=document.querySelector('.demo');if(banner)banner.textContent=preview?'STORE PREVIEW · Test orders only · Do not send money':'GLOW LAB STORE · Details → payment → screenshot → submit';const footer=document.querySelector('#research-notice');if(footer)footer.textContent='Research materials are not for human or animal use.';if(!state.affiliate)document.title=preview?'Glow Lab · Store Preview':'Glow Lab · Store'}

function paymentInstructions(o,links,preview=false){const test=o.is_test!==false||preview,labels={venmo:'Venmo',paypal:'PayPal',cashapp:'Cash App',zelle:'Zelle'},payable=o.status==='awaiting_payment',recipient=links[o.payment_method]||'';return `<h2>Step 2 · Pay your total</h2><div class="row"><span>Amount to send</span><strong class="price">${money(o.total)}</strong></div><div class="row"><span>Order number</span><strong>${esc(o.id)}</strong></div><div class="row"><span>Payment method</span><strong>${esc(labels[o.payment_method]||o.payment_method)}</strong></div>${test?'<div class="notice">Preview only · Do not send money. Payment buttons are disabled for test orders.</div>':''}${payable?`<p>Send the exact total shown above. Include your order number in the payment note where available.</p>${recipient?o.payment_method==='zelle'?`<label>Zelle recipient<input readonly value="${esc(recipient)}"></label><p>Open your bank’s Zelle service, confirm the recipient, and enter the total. Zelle is paid through your bank.</p>`:test?`<button type="button" disabled>Open ${esc(labels[o.payment_method])} · preview only</button>`:`<a class="payment-link" href="${esc(recipient)}" target="_blank" rel="noopener noreferrer">Open ${esc(labels[o.payment_method])}</a><p class="muted">Confirm the recipient and enter the amount in the payment service. Return to this open tab after paying, upload your screenshot, and press Submit order. Do not close checkout.</p>`:'<div class="notice">This payment method is not configured. Contact the store before sending payment.</div>'}`:o.status==='payment_submitted'?'<div class="notice">Your screenshot is awaiting review. Do not send another payment.</div>':['paid','shipped'].includes(o.status)?`<div class="notice">Payment received. Your order is ${o.status==='shipped'?'shipped':'now in queue'}. No further payment is needed.</div>`:'<div class="notice">This order is closed. Do not send payment.</div>'}`}
function paymentPreview(){const links=state.admin.settings.payment_links;return `<section class="panel"><h2>Customer payment screen preview</h2><p class="muted">Sample order and amount. These previews never open payment services.</p><div class="grid">${['venmo','paypal','cashapp','zelle'].map(payment_method=>`<section class="card">${paymentInstructions({id:'PREVIEW-ORDER',total:12500,payment_method,status:'awaiting_payment',is_test:true},links,true)}</section>`).join('')}</div><p>After payment, customers attach a screenshot and transaction reference. Staff verify the actual funds before marking the order paid.</p></section>`}
function orderLabel(o){return o.status==='awaiting_payment'?(o.checkout_stage==='draft'?'Draft · waiting for payment':'Waiting for payment'):({payment_submitted:'Submitted · payment review',paid:'Payment received · in queue',shipped:'Shipped',expired:'Expired · follow up if paid',canceled:'Canceled'}[o.status]||o.status)}
function renderOrder(){const o=state.order;const test=o.is_test!==false;const pending=o.status==='awaiting_payment',review=o.status==='payment_submitted';app.innerHTML=`<div class="intro"><div class="eyebrow">${pending?'Checkout · finish your order':review?'Order submitted':'Order status'}</div><h1>${esc(o.id)}</h1><p><span class="badge ${o.status}">${esc(orderLabel(o))}</span></p><p class="muted">${pending?'Your draft is saved. Pay below, attach your screenshot, then submit. Already paid? Upload your screenshot; do not pay again.':review?'Your screenshot and order were received together. Once we verify your payment, your order will be placed in queue. Do not pay again.':'Keep your private checkout link to check order status.'}</p></div><div class="split"><section class="panel">${paymentInstructions(o,state.catalog?.settings.payment_links||{})}<div class="actions">${button('Copy amount','copy-amount','secondary')}${button('Copy order number','copy-order','secondary')}${button('Refresh status','refresh-order','secondary')}${state.token?button('Copy private return link','copy-checkout-link','secondary'):''}</div><p>Reservation ends: ${new Date(o.expires*1000).toLocaleString()}. Orders with a submitted receipt wait for staff review.</p><h3>Items</h3>${o.items.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.quantity}</span><span>${money(i.amount)}</span></div>`).join('')}${totals(o)}</section><section class="panel"><h2>${review?'Payment screenshot received':'Step 3 · Screenshot and submit'}</h2><p class="muted">${test?'Upload a sample screenshot and reference. Do not send money.':'After paying, attach your screenshot and transaction reference, then submit your order. Staff will verify payment in the receiving account.'} Uploading does not mark the order paid.</p>${['awaiting_payment','payment_submitted'].includes(o.status)?`<form id="receipt">${!o.customer.phone?`<label>Phone number (for order questions)<input name="phone" type="tel" autocomplete="tel" required maxlength="32"></label>`:''}<label>Transaction reference (optional)<input name="reference" maxlength="100" value="${esc(o.payment_reference||'')}" placeholder="${test?'DEMO-TRANSACTION-123':'Transaction ID or payment reference'}"></label><label>Screenshot · PNG, JPEG, or WebP, up to 3 MB<input name="screenshot" type="file" accept="image/png,image/jpeg,image/webp" required></label><button type="submit">${review?'Replace payment screenshot':test?'Submit test order':'Submit order'}</button><p class="error" id="receipt-error" role="alert"></p></form>`:`<p>${o.status==='expired'?'The reservation expired. If you already paid, contact the store with this order number and screenshot. Do not pay again or start another checkout.':'This order no longer accepts receipt uploads.'}</p>`}${o.has_receipt?'<p>Receipt attached. Staff can view it securely in management.</p>':''}<div class="notice">Affiliate commission: ${o.commission_status==='eligible'?'eligible after verified payment':'not eligible until payment is verified'}. Affiliate credit is reviewed after payment verification.</div>${pending?'':button(test?'Start another test order':'Start another order','new-order','secondary')}</section></div>`}
async function loadAdmin(){if(location.hash.startsWith('#staff=')){loadStaffSetup();return}try{state.admin=await api('/api/admin/data');renderMode(state.admin.settings);renderAdmin()}catch{login()}}
function login(){app.innerHTML=`<div class="intro"><div class="eyebrow">Private management</div><h1>Your store workspace.</h1><p class="muted">Staff: use your email and password. Owner: leave email blank and use your existing management password.</p></div><form id="login" class="panel login-panel"><label>Staff email (leave blank for owner)<input name="email" type="email" autocomplete="username"></label><label>Password<input name="password" type="password" autocomplete="current-password" required></label><button type="submit">Sign in</button><p id="login-error" class="error" role="alert"></p></form><form id="staff-reset" class="panel login-panel"><h2>Need a setup or reset link?</h2><label>Management email<input name="email" type="email" required autocomplete="email"></label><button type="submit">Email private link</button><p class="error" role="alert"></p></form>`}
const field=(name,label,value='',type='text')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="0" step="0.01"':''}></label>`;
function renderAdmin(){const d=state.admin,live=d.orders.filter(o=>o.is_test===false),paid=live.filter(o=>['paid','shipped'].includes(o.status)),pending=live.filter(o=>['awaiting_payment','payment_submitted'].includes(o.status));app.innerHTML=`<div class="row"><div><div class="eyebrow">Glow GLP’s · management</div><h1>Store control, simplified.</h1></div>${button('Sign out','logout','secondary')}</div><div class="metrics">${[[live.filter(o=>o.checkout_stage!=='draft'||['paid','shipped'].includes(o.status)).length,'Live orders submitted'],[money(paid.reduce((n,o)=>n+o.total,0)),'Verified payments'],[money(pending.reduce((n,o)=>n+o.total,0)),'Drafts and payments awaiting review'],[money(paid.reduce((n,o)=>n+o.commission,0)),'Eligible commission estimate']].map(([n,label])=>`<div class="panel metric"><strong>${n}</strong><small>${label}</small></div>`).join('')}</div><p class="muted">${d.orders.length-live.length} test orders excluded from sales totals · Checkout: ${d.settings.demo!==false?'preview':'live'}</p><div class="tabs" role="group" aria-label="Management views">${['orders','products','coupons','affiliates','customers','emails','shipping','settings',...(d.owner?['staff']:[])].map(t=>`<button data-action="tab" data-tab="${t}" class="${t===state.tab?'selected':''}">${t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div><section id="admin-content">${adminContent()}</section>`}
function adminContent(){const d=state.admin;if(state.tab==='staff')return staffPanel();if(state.tab==='emails')return emailPanel();if(state.tab==='customers')return customersAdmin();if(state.tab==='shipping')return shippingPanel();if(state.tab==='orders')return `<div class="panel tablewrap"><h2>Orders and checkout drafts</h2><p>Drafts are saved before customers open a payment app. Submitted orders have a screenshot awaiting review. Verify the funds before processing.</p><div class="actions" aria-label="Order queues">${[['awaiting_payment','Waiting for payment'],['payment_submitted','Payment review'],['paid','Payment received / in queue'],['shipped','Shipped'],['expired','Expired / follow up']].map(([status,label])=>`<button data-action="order-queue" data-status="${status}" class="${state.orderStatus===status?'selected':'secondary'}">${label} (${d.orders.filter(o=>o.is_test===false&&o.status===status).length})</button>`).join('')}</div><div class="fields"><label>Find an order<input id="order-search" type="search" value="${esc(state.orderSearch)}" placeholder="Order number, customer, email or affiliate"></label><label>Status<select id="order-status">${['all','awaiting_payment','payment_submitted','paid','shipped','canceled','expired'].map(v=>`<option value="${v}" ${state.orderStatus===v?'selected':''}>${v.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Order type<select id="order-mode">${['all','live','test'].map(v=>`<option value="${v}" ${state.orderMode===v?'selected':''}>${v}</option>`).join('')}</select></label></div><div id="order-results">${orderRows()}</div></div><div id="detail"></div>`;
if(state.tab==='products')return `<div class="split"><section class="panel"><h2>Catalog</h2><p class="muted">Stock means units available after reservations.</p>${d.products.map(p=>`<div class="line"><div class="row"><strong>${esc(p.name)}</strong><button data-action="edit-product" data-id="${p.id}" class="secondary">Edit</button></div><small>${esc(p.sku)} · ${money(p.price)} · ${p.stock} available${p.stock_pool?' · Shared: '+esc(p.stock_pool):''} · ${p.active?'Active':'Hidden'}</small></div>`).join('')}</section><form id="product" class="panel"><h2 id="product-title">Add a product</h2><input name="id" type="hidden">${field('name','Product name')}${field('sku','Unique SKU')}${field('price','Selling price ($)',25,'number')}${field('stock','Available units',10,'number')}<label>Shared stock group (optional)<input name="stock_pool" maxlength="60" placeholder="Leave blank for separate stock"></label><p class="muted">Products in the same group share one available count. Changing that count updates the whole group.</p><label>Visibility<select name="active"><option value="1">Active</option><option value="0">Hidden</option></select></label><button type="submit">Save product</button><p class="error" role="alert"></p></form></div>`;
if(state.tab==='coupons')return `<div class="split"><section class="panel"><h2>Coupon codes</h2>${d.coupons.map(c=>`<div class="line"><div class="row"><strong>${esc(c.code)}</strong><button data-action="edit-coupon" data-code="${esc(c.code)}" class="secondary">Edit</button></div><small>${c.kind==='percent'?c.value+'%':money(c.value)} off · ${c.used}/${c.max_uses} uses reserved or paid · ${c.active?'Active':'Disabled'} · ${c.affiliate?'Credits '+esc(d.affiliates.find(a=>a.slug===c.affiliate)?.name||c.affiliate):'General promotion'}</small></div>`).join('')}</section><form id="coupon-form" class="panel"><h2>Add or update a coupon</h2>${field('code','Code')}<label>Affiliate to credit<select name="affiliate"><option value="">General promotion</option>${d.affiliates.filter(a=>a.goaffpro_id).map(a=>`<option value="${esc(a.slug)}">${esc(a.name)}${a.active?'':' — disabled'}</option>`).join('')}</select></label><p class="muted">An affiliate coupon credits its owner, even when the customer arrived through another affiliate’s link. General promotions keep the storefront referral.</p><label>Discount type<select name="kind"><option value="percent">Percentage</option><option value="fixed">Dollar amount off</option></select></label>${field('value','Percentage or dollar amount',20,'number')}${field('minimum','Minimum product subtotal ($)',0,'number')}${field('max_uses','Maximum uses',100,'number')}${field('expiry_date','Expiration (optional)','','date')}<label>Status<select name="active"><option value="1">Active</option><option value="0">Disabled</option></select></label><button type="submit">Save coupon</button><p class="error" role="alert"></p></form></div>`;
if(state.tab==='affiliates')return `${goaffproPanel()}<div class="split"><section class="panel"><h2>Personalized storefronts</h2><div id="photo-link-result" aria-live="polite"></div><div class="notice">Storefront attribution works. Verified live orders can be reported to GoAffPro. Test orders never create real commissions. Affiliate sign-in is still being built.</div>${d.affiliates.map(a=>`<div class="line"><div class="row"><strong>${esc(a.name)}</strong><div class="actions"><button data-action="copy-storefront" data-slug="${esc(a.slug)}" class="secondary">Copy store link</button><button data-action="photo-link" data-slug="${esc(a.slug)}" class="secondary" ${a.active?'':'disabled'}>Photo upload link</button><button data-action="edit-affiliate" data-slug="${esc(a.slug)}" class="secondary">Edit</button></div></div><p><a href="/store-next/${esc(a.slug)}" target="_blank" rel="noopener">/${esc(a.slug)}</a> · ${a.commission_bps/100}% estimate · ${a.active?'Active':'Disabled'}</p><small>${esc(a.bio)}</small></div>`).join('')}</section><form id="affiliate" class="panel"><h2 id="affiliate-title">Add or update an affiliate</h2><p class="muted">Imported storefront links stay fixed when you edit their name or introduction.</p>${field('slug','Store link slug (e.g. sarah)')}${field('name','Display name')}<label>Introduction<textarea name="bio" maxlength="500"></textarea></label>${field('goaffpro_id','GoAffPro affiliate ID (from your connection preview)')}${field('commission_bps','Commission basis points (1500 = 15%)',1500,'number')}<label>Status<select name="active"><option value="1">Active</option><option value="0">Disabled</option></select></label><button type="submit">Save affiliate</button><p class="error" role="alert"></p></form></div>`;
return `<form id="settings" class="panel"><h2>Shipping and payment recipients</h2><div class="notice">Saved recipients appear on the payment screen after an order is placed. Preview orders never open payment links.</div>${field('shipping_cents','Flat shipping ($)',d.settings.shipping_cents/100,'number')}${field('free_shipping_cents','Free shipping above discounted subtotal ($; 0 disables)',d.settings.free_shipping_cents/100,'number')}${field('venmo','Official Venmo HTTPS link',d.settings.payment_links.venmo)}${field('paypal','Official PayPal HTTPS link',d.settings.payment_links.paypal)}${field('cashapp','Official Cash App HTTPS link',d.settings.payment_links.cashapp)}${field('zelle','Zelle enrolled business email, phone, or tag',d.settings.payment_links.zelle)}<button type="submit">Save settings</button><p class="error" role="alert"></p><p class="muted">Customer accounts and rewards are built. ${d.email?.configured?'Account setup emails are connected; check recent email activity.':'Account setup links currently need manual email delivery.'} ${d.shipstation?.enabled?'ShipStation automatic transfer is enabled.':d.shipstation?.connected?'ShipStation is connected; enable automatic transfer in Shipping.':'ShipStation is not connected; shipments need manual handling.'}</p></form>${checkoutSettings()}${emailPanel()}${paymentPreview()}`}
function shippingPanel(){const g=state.admin.shipstation||{},orders=state.admin.orders.filter(o=>o.is_test===false&&['paid','shipped'].includes(o.status));return `<section class="panel"><h2>ShipStation connection</h2><p role="status">${g.enabled?'Automatic transfer enabled · '+esc(g.store_name):g.connected?'Connection verified · choose a store and enable transfer':g.configured?'Credentials saved · check connection':'Waiting for ShipStation V1 credentials in Netlify'}</p><p>Only live orders with a screenshot and verified payment are transferred. No postage is purchased automatically. Review package weights and service in ShipStation. Tracking is checked every five minutes after a shipment is created.</p>${button('Check ShipStation connection','shipstation-check','secondary')}${!g.configured?'<div class="notice">Save SHIPSTATION_API_KEY and SHIPSTATION_API_SECRET privately in Netlify’s production Functions environment, then redeploy. Do not paste keys into chat or this dashboard.</div>':''}${g.connected?`<form id="shipstation-settings"><label>ShipStation manual store<select name="store_id" required>${g.stores.map(x=>`<option value="${x.id}" ${g.store_id===x.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label>Automatic order transfer<select name="enabled"><option value="0" ${!g.enabled?'selected':''}>Paused</option><option value="1" ${g.enabled?'selected':''}>Enabled</option></select></label><button type="submit" ${g.stores.length?'':'disabled'}>Save shipping connection</button><p class="error" role="alert"></p>${!g.stores.length?'<p>Create a Manual Store in ShipStation, then check the connection again. WooCommerce stores are excluded from this selector.</p>':''}</form>`:''}<h3>Verified orders and shipping status</h3>${orders.map(o=>`<div class="line"><strong>${esc(o.id)} · ${esc(o.customer.name)}</strong><p>${esc(o.shipstation_status||'not sent')} ${o.tracking?' · '+esc(o.tracking):''}</p>${o.shipstation_message?`<p class="muted">${esc(o.shipstation_message)}</p>`:''}<div class="actions"><button data-action="shipment-preview" data-id="${o.id}" class="secondary">Review shipment data</button>${o.status==='paid'?`<button data-action="shipstation-send" data-id="${o.id}" ${g.enabled?'':'disabled'}>Check / send order</button>${o.shipstation_order_id?`<button data-action="shipstation-tracking" data-id="${o.id}" class="secondary">Check tracking</button>`:''}`:''}</div></div>`).join('')||'<p>No verified live orders yet.</p>'}<pre id="shipment-payload" class="payload"></pre></section>`}
function orderRows(){const orders=state.admin.orders.filter(o=>(state.orderStatus==='all'||o.status===state.orderStatus)&&(state.orderMode==='all'||(state.orderMode==='live')===(o.is_test===false))&&[o.id,o.customer.name,o.customer.email,o.affiliate||''].join(' ').toLowerCase().includes(state.orderSearch.toLowerCase()));return orders.length?`<table><thead><tr><th>Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Affiliate</th><th>Review</th></tr></thead><tbody>${orders.map(o=>`<tr><td>${esc(o.id)}${o.is_test!==false?'<br><small>Test order</small>':''}</td><td>${esc(o.customer.name)}<br><small>${esc(o.customer.email)}</small></td><td>${money(o.total)}</td><td><span class="badge ${o.status}">${esc(orderLabel(o))}</span></td><td>${esc(o.affiliate||'Direct')}</td><td><button data-action="order-detail" data-id="${o.id}">Open</button></td></tr>`).join('')}</tbody></table>`:'<p>No matching orders.</p>'}
function checkoutSettings(){const d=state.admin,stock=d.products.filter(p=>p.active&&p.stock>0).length,recipients=Object.values(d.settings.payment_links||{}).filter(Boolean).length;return `<form id="checkout-settings" class="panel account-ledger"><h2>Checkout mode</h2><p>${stock} active products in stock · ${recipients} payment recipients saved.</p><div class="notice">Live checkout accepts real orders, reserves inventory and rewards points, and displays your saved payment instructions. Staff must verify payment before points are earned or affiliate orders are reported. Sales tax will not be charged, matching your current checkout.</div><label>Mode<select name="mode"><option value="preview" ${d.settings.demo!==false?'selected':''}>Preview · test orders</option><option value="live" ${d.settings.demo===false?'selected':''}>Live · real orders</option></select></label><label><input name="tax_mode" type="checkbox" value="none" required ${d.settings.tax_mode==='none'?'checked':''}> Confirm this checkout charges no sales tax</label><button type="submit">Save checkout mode</button><p class="error" role="alert"></p><p class="muted">Before opening, save accurate stock and check each payment recipient. ${d.email?.configured?'Automatic email is configured.':'Automatic email is not connected yet.'} ${d.shipstation?.enabled?'Automatic ShipStation transfer is enabled.':'Finish the ShipStation connection in Shipping.'} GoAffPro’s first live sale still needs its reporting result checked.</p></form>`}
function emailPanel(){const e=state.admin.email||{};return `<section class="panel account-ledger"><h2>Automatic emails</h2><p role="status">${esc(e.message||'Waiting for email connection.')}</p><p>Sender: <strong>${esc(e.from||'support@glowglps.com')}</strong><br>Replies: ${esc(e.reply_to||'support@glowglps.com')}</p><p>Checkout return links, submitted-order confirmations, verified-payment updates, shipping updates, account setup and password resets are built. Preview orders never send emails. Existing customer balances do not trigger a bulk email.</p>${!e.configured?`<div class="notice"><ol><li>Open <a href="https://resend.com" target="_blank" rel="noopener noreferrer">Resend</a> and add your sending domain.</li><li>Add Resend’s domain-verification DNS records, then wait for Verified.</li><li>Create a sending API key and save it privately in Netlify’s Functions environment as <code>RESEND_API_KEY</code>.</li><li>Also save <code>STORE_EMAIL_FROM=support@glowglps.com</code>, <code>STORE_EMAIL_REPLY_TO=support@glowglps.com</code>, and <code>STORE_EMAIL_ENABLED=1</code>, then redeploy.</li></ol><p>Keep API keys out of chat and GitHub. Make sure the reply address is a mailbox you can read; domain verification does not create that mailbox.</p></div>`:''}<form id="email-test" data-key="${crypto.randomUUID()}"><label>Your email for the connection test<input name="email" type="email" autocomplete="email" required maxlength="150"></label><button type="submit" ${e.configured?'':'disabled'}>Send connection test</button><p class="error" role="alert"></p></form><h3>Recent email activity</h3><p class="muted">Accepted means Resend accepted the request. Check the inbox or Resend delivery logs to confirm delivery. Temporary failures retry automatically every five minutes.</p><div class="tablewrap"><table><thead><tr><th>Time</th><th>Email</th><th>Recipient</th><th>Status</th><th>Details</th></tr></thead><tbody>${(e.jobs||[]).map(j=>`<tr><td>${new Date(j.created*1000).toLocaleString()}</td><td>${esc(j.kind.replaceAll('_',' '))}<br>${esc(j.related_id||'')}</td><td>${esc(j.to)}</td><td>${esc(j.status)}</td><td>${esc(j.message)}${['retry','rejected'].includes(j.status)?`<button data-action="retry-email" data-id="${esc(j.id)}" class="secondary">Retry after checking settings</button>`:''}</td></tr>`).join('')||'<tr><td colspan="5">No email activity yet.</td></tr>'}</tbody></table></div></section>`}
function goaffproPanel(){const g=state.admin.goaffpro||{},preview=state.goaffproPreview;return `<section class="panel integration-panel"><h2>GoAffPro connection</h2><p role="status">${g.verified?'Connection verified'+(g.checked_at?' · '+new Date(g.checked_at*1000).toLocaleString():''):g.configured?'Key configured · connection not yet verified':'Waiting for your GoAffPro access token in Netlify'}</p><p class="muted">${g.reporting_read_verified?'Order lookup and self-purchase read permissions checked.':'Check order reporting permissions before launch.'}</p><div class="actions">${button('Check GoAffPro connection','goaffpro-check','secondary')}${button('Check order reporting permissions','goaffpro-reporting-check','secondary')}<button type="button" data-action="create-storefronts" ${g.configured?'':'disabled'}>Create approved storefronts</button></div><p class="muted">Create a named store link for every approved affiliate. Existing links, custom introductions and disabled storefronts are preserved. GoAffPro determines commissions using your program rules. Verified live orders report automatically; test orders stay local.</p>${preview?`<div class="tablewrap"><table><thead><tr><th>Affiliate</th><th>GoAffPro ID</th><th>Referral code</th></tr></thead><tbody>${preview.affiliates.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.id)}</td><td>${esc(a.ref_code)}</td></tr>`).join('')}</tbody></table></div><p>${preview.affiliates.length} approved profiles returned${preview.has_more?' · more profiles are available':''}.</p>`:''}</section>`}
const storeUrl=slug=>(location.origin||'https://glowglps.com')+'/store-next/'+encodeURIComponent(slug);
async function importStorefronts(button){let offset=0,created=0,existing=0,skipped=0;const pages=new Set();for(let page=0;page<100;page++){button.textContent='Creating storefronts… '+created+' created';const result=await api('/api/admin/goaffpro/storefronts',{offset});const key=result.affiliates.map(a=>a.id).join(',');if(pages.has(key)&&result.affiliates.length)throw new Error('The affiliate list repeated a page. Created links are saved; please contact support before retrying.');pages.add(key);created+=result.imported.created;existing+=result.imported.existing;skipped+=result.imported.skipped;state.goaffproPreview=result;if(!result.has_more){await loadAdmin();toast(created+' storefronts created · '+existing+' already existed'+(skipped?' · '+skipped+' skipped':'')+'.');return}offset+=result.limit}throw new Error('The import reached its page limit. Created storefronts are saved.')}
async function profileApi(path,data){const opts={headers:{'X-Store-Request':'1','X-Profile-Token':state.profileToken}};if(data!==undefined){opts.method='POST';opts.headers['Content-Type']='application/json';opts.body=JSON.stringify(data)}const r=await fetch('/.netlify/functions/store-next?route='+encodeURIComponent('/affiliate-profile/'+state.profileSlug+path),opts);const result=await r.json();if(!r.ok)throw new Error(result.error||'Request failed');return result}
async function loadProfile(){state.profileSlug=decodeURIComponent(location.pathname.split('/').filter(Boolean).pop());const token=(location.hash||'').slice(1);if(token){state.profileToken=token;sessionStorage.setItem('glow_photo_'+state.profileSlug,token);history.replaceState(null,'',location.pathname)}else state.profileToken=sessionStorage.getItem('glow_photo_'+state.profileSlug)||'';try{renderProfile(await profileApi(''))}catch(e){app.innerHTML=`<h1>Photo upload link unavailable</h1><p class="error">${esc(e.message)}</p>`}}
function renderProfile(profile){app.innerHTML=`<section class="panel profile-panel"><div class="eyebrow">Your affiliate storefront</div><h1>Hi, ${esc(profile.name)}.</h1><p>Add a photo so customers recognize you on your Glow GLP’s store.</p>${profile.photo_url?`<img class="affiliate-avatar profile-avatar" src="${esc(profile.photo_url)}" alt="Your current photo">`:'<p>No photo uploaded yet.</p>'}<form id="affiliate-photo"><label>Your photo · JPEG, PNG, or WebP, up to 3 MB<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label><p class="muted">Your photo will be cropped to a square. Choose one with your face near the center.</p><button type="submit">Save my photo</button><p class="error" role="alert"></p></form>${profile.photo_url?button('Remove my photo','remove-profile-photo','secondary'):''}<p><a href="${esc(storeUrl(profile.slug))}" target="_blank" rel="noopener">View my storefront</a></p><small>This private upload link changes only your photo. Keep it private.</small></section>`}

function detail(id){const o=state.admin.orders.find(o=>o.id===id);document.querySelector('#detail').innerHTML=`<section class="panel order"><h2>${esc(o.id)} · ${money(o.total)}${o.is_test!==false?' · Test order':''}</h2><p><span class="badge ${o.status}">${esc(orderLabel(o))}</span></p><p>${esc(o.customer.name)} · ${esc(o.customer.email)}<br>${o.customer.phone?`<a href="tel:${esc(o.customer.phone)}">${esc(o.customer.phone)}</a>`:'Phone not collected on this older order'}<br>${esc(o.customer.address)}, ${esc(o.customer.city)}, ${esc(o.customer.state)} ${esc(o.customer.zip)}</p>${o.items.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.quantity}</span><span>${money(i.amount)}</span></div>`).join('')}${totals(o)}<p>Method: ${esc(o.payment_method)} · Reference: ${esc(o.payment_reference||'Not submitted')}</p><p>Affiliate: ${esc(o.affiliate||'None')} · Estimated commission: ${money(o.commission)} (${o.commission_status.replaceAll('_',' ')})</p>${o.has_receipt?`<img class="receipt" src="/.netlify/functions/store-next?route=/admin/receipt/${o.id}" alt="Customer-uploaded payment receipt"><p class="muted">Verify against the actual account transaction before marking paid.</p>`:''}<div class="actions">${['awaiting_payment','payment_submitted'].includes(o.status)?`<button data-action="paid" data-id="${o.id}" ${o.is_test===false&&!o.has_receipt?'disabled':''}>Mark payment received</button>${o.is_test===false&&!o.has_receipt?'<p class="muted">Waiting for the customer’s payment screenshot. A payment-received email cannot be sent yet.</p>':''}<button data-action="cancel" data-id="${o.id}" class="danger">Cancel and release stock</button>`:''}${o.status==='paid'?`<label>Tracking number<input id="tracking"></label><button data-action="shipped" data-id="${o.id}">Mark shipped</button>`:''}</div>${['paid','shipped'].includes(o.status)&&o.affiliate?`<h3>GoAffPro reporting</h3><p>${esc((o.goaffpro_status||'not_ready').replaceAll('_',' '))}</p>${o.goaffpro_message?`<p class="muted">${esc(o.goaffpro_message)}</p>`:''}<div class="actions"><button data-action="goaffpro-preview" data-id="${o.id}" class="secondary">Preview affiliate report</button>${o.is_test===false?`<button data-action="goaffpro-report" data-id="${o.id}" class="secondary">${o.goaffpro_status==='needs_review'?'Check reporting status':'Report / check GoAffPro'}</button>`:'<span class="muted">Test order · no sale sent</span>'}</div><pre id="affiliate-report-preview" class="payload"></pre>`:''}${o.tracking?`<p>Tracking: ${esc(o.tracking)}</p>`:''}</section>`;document.querySelector('#detail').scrollIntoView({behavior:'smooth',block:'start'})}
function fill(form,values){for(const [k,v]of Object.entries(values))if(form.elements[k])form.elements[k].value=v??''}
document.addEventListener('input',e=>{if(e.target.id==='search')document.querySelectorAll('#products .card').forEach(c=>c.hidden=!c.dataset.name.includes(e.target.value.toLowerCase()))});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;b.disabled=true;try{if(['add','plus','minus'].includes(action)){const id=Number(b.dataset.id),old=state.cart.get(id)||0,newQty=old+(action==='minus'?-1:1);const p=state.catalog.products.find(p=>p.id===id);if(newQty>p.stock){toast('No more stock available.');return}if(newQty<=0)state.cart.delete(id);else state.cart.set(id,newQty);try{await calculate()}catch(err){if(old)state.cart.set(id,old);else state.cart.delete(id);throw err}if(state.shoppingView==='bag')renderBag();else{renderStore();if(action==='add')toast('Added to your bag. Use View bag when you’re ready.')}}
else if(action==='coupon'){const previous=state.coupon;state.coupon=document.querySelector('#coupon').value.trim();try{await calculate()}catch(err){state.coupon=previous;throw err}renderBag();toast('Coupon updated.')}
else if(action==='order-queue'){state.orderStatus=b.dataset.status;state.orderMode='live';renderAdmin();return}
else if(action==='checkout'){await calculate();checkout()}
else if(action==='back')renderBag();
else if(action==='view-bag'){if(!state.catalog){state.catalog=await api('/api/catalog');try{state.customer=await api('/api/account')}catch{state.customer=null}}await calculate();renderBag();document.querySelector('#app').scrollIntoView({block:'start'})}
else if(action==='browse-store'){renderStore();document.querySelector('#collection').scrollIntoView({block:'start'})}
else if(action==='copy-checkout-link'){await navigator.clipboard.writeText(location.origin+'/store-next/'+(state.order.affiliate||'')+'#order='+state.order.id+'.'+state.token);toast('Private return link copied. Keep it for yourself.')}
else if(action==='copy-amount'||action==='copy-order'){await navigator.clipboard.writeText(action==='copy-order'?state.order.id:(state.order.total/100).toFixed(2));toast('Copied.')}
else if(action==='refresh-order'){state.order=await api('/api/orders/'+state.order.id,undefined,state.token);renderOrder()}
else if(action==='new-order'){sessionStorage.removeItem('glow_cart');state.points=0;sessionStorage.removeItem('glow_order');state.order=null;state.token='';state.cart.clear();state.quote=null;state.coupon='';state.catalog=await api('/api/catalog');renderMode(state.catalog.settings);try{state.customer=await api('/api/account')}catch{state.customer=null}renderStore()}
else if(action==='apply-points'){const value=Number(document.querySelector('#use-points').value);if(!Number.isSafeInteger(value)||value<0)throw new Error('Enter a whole number of points.');const old=state.points;state.points=value;try{await calculate()}catch(e){state.points=old;throw e}renderBag()}
else if(action==='customer-logout'){await api('/api/account/logout',{});state.customer=null;state.points=0;renderAccountLogin();toast('Signed out.')}
else if(action==='account-order'){state.catalog=await api('/api/catalog');state.order=await api('/api/orders/'+b.dataset.id);state.token='';renderOrder()}
else if(action==='customer-setup-link'){const r=await api('/api/admin/customer/setup-link',{customer_id:b.dataset.id});const url=location.origin+'/store-next/account-setup#'+r.customer_id+'.'+r.token;const target=document.querySelector('#customer-link-result');target.innerHTML=`<div class="notice"><strong>Private account setup link</strong><p>Send this link only to <b>${esc(r.email)}</b> by email. Opening it lets the recipient set a password and access that customer’s points. It expires in 24 hours and replaces any prior setup link.</p><input id="customer-setup-link" readonly aria-label="Private customer setup link">${button('Copy setup link','copy-customer-link','secondary')}</div>`;target.querySelector('input').value=url;target.scrollIntoView({behavior:'smooth',block:'center'})}
else if(action==='retry-email'){const r=await api('/api/admin/email/retry',{id:b.dataset.id});await loadAdmin();toast(r.message||r.status)}
else if(action==='send-customer-setup'){if(!confirm('Email a private setup/reset link to this customer’s saved email address?'))return;const r=await api('/api/admin/customer/send-setup',{customer_id:b.dataset.id});await loadAdmin();state.customerAdmin=await api('/api/admin/customers');renderAdmin();toast(r.email?.message||'Setup email requested.')}
else if(action==='copy-customer-link'){await navigator.clipboard.writeText(document.querySelector('#customer-setup-link').value);toast('Copied. Email it only to the customer address shown.')}
else if(action==='commit-rewards-import'){if(!state.migrationPreview||state.migrationPreview.conflicts.length)throw new Error('Resolve migration conflicts first.');const r=await api('/api/admin/rewards/import',{batch_id:state.migrationPreview.batch_id});state.migrationPreview=null;state.customerAdmin=await api('/api/admin/customers');renderAdmin();toast(r.added+' balances imported · '+r.existing+' already existed · '+r.held+' held for review.')}
else if(action==='reconcile-rewards-import'){if(!state.migrationPreview)throw new Error('Preview balances first.');const r=await api('/api/admin/rewards/reconcile',{batch_id:state.migrationPreview.batch_id});state.migrationPreview=null;state.customerAdmin=await api('/api/admin/customers');renderAdmin();toast(r.added+' balances added · '+r.updated+' source balances reconciled · '+r.points_delta+' points difference.')}
else if(action==='customer-ledger'){const a=state.customerAdmin.customers.find(a=>a.id===b.dataset.id),target=document.querySelector('#customer-ledger');target.innerHTML=`<section class="panel"><h2>${esc(a.name)} · points history</h2>${ledgerTable(state.customerAdmin.ledger.filter(e=>e.customer_id===a.id))}<form id="rewards-adjust" data-key="${crypto.randomUUID()}"><input name="customer_id" type="hidden" value="${esc(a.id)}"><label>Adjustment · positive to add, negative to subtract<input name="points" type="number" step="1" required></label><label>Reason<input name="note" maxlength="500" required></label><button type="submit">Save points adjustment</button><p class="error" role="alert"></p></form><p class="muted">Adjustments are recorded in the ledger. Negative adjustments can leave a balance owing; future earnings offset it. Refunds and GoAffPro reversals still need separate staff handling.</p></section>`;target.scrollIntoView({behavior:'smooth'})}
else if(action==='goaffpro-check'){state.goaffproPreview=null;const result=await api('/api/admin/goaffpro/check',{});state.goaffproPreview=result;await loadAdmin();toast('GoAffPro connection verified.')}
else if(action==='goaffpro-reporting-check'){const r=await api('/api/admin/goaffpro/reporting-check',{});await loadAdmin();toast(r.message)}
else if(action==='goaffpro-report'){const r=await api('/api/admin/goaffpro/report',{id:b.dataset.id});await loadAdmin();detail(b.dataset.id);toast(r.message||('GoAffPro: '+r.status))}
else if(action==='goaffpro-preview'){const r=await api('/api/admin/goaffpro/preview',{id:b.dataset.id});document.querySelector('#affiliate-report-preview').textContent=JSON.stringify(r,null,2)}
else if(action==='tab'){state.tab=b.dataset.tab;if(state.tab==='customers')state.customerAdmin=await api('/api/admin/customers');renderAdmin()}
else if(action==='revoke-staff'){if(!confirm('Remove management access for this staff member?'))return;await api('/api/admin/staff/revoke',{id:b.dataset.id});await loadAdmin();toast('Staff access removed.')}
else if(action==='logout'){await api('/api/admin/logout',{});state.goaffproPreview=null;state.admin=null;login()}
else if(action==='shipstation-check'){await api('/api/admin/shipstation/check',{});await loadAdmin();toast('ShipStation connection checked.')}
else if(action==='shipstation-send'||action==='shipstation-tracking'){const result=await api('/api/admin/shipstation/'+(action==='shipstation-send'?'send':'tracking'),{id:b.dataset.id});await loadAdmin();toast(result.message||result.status)}
else if(action==='shipment-preview'){const result=await api('/api/admin/shipment-preview',{id:b.dataset.id});document.querySelector('#shipment-payload').textContent=JSON.stringify(result,null,2)}else if(action==='order-detail')detail(b.dataset.id);
else if(action==='edit-product'){(()=>{const p=state.admin.products.find(p=>p.id===Number(b.dataset.id));fill(document.querySelector('#product'),{...p,stock_pool:p.stock_pool||'',price:p.price/100})})();document.querySelector('#product-title').textContent='Edit product'}
else if(action==='edit-coupon'){const c=state.admin.coupons.find(c=>c.code===b.dataset.code);fill(document.querySelector('#coupon-form'),{...c,affiliate:c.affiliate||'',value:c.kind==='fixed'?c.value/100:c.value,minimum:c.minimum/100,expiry_date:c.expires?new Date(c.expires*1000).toISOString().slice(0,10):''})}
else if(action==='edit-affiliate'){const form=document.querySelector('#affiliate');fill(form,state.admin.affiliates.find(a=>a.slug===b.dataset.slug));form.elements.slug.readOnly=true;document.querySelector('#affiliate-title').textContent='Edit storefront';form.scrollIntoView({behavior:'smooth',block:'start'})}
else if(action==='copy-storefront'){await navigator.clipboard.writeText(storeUrl(b.dataset.slug));toast('Storefront link copied.')}
else if(action==='create-storefronts')await importStorefronts(b);
else if(action==='photo-link'){const r=await api('/api/admin/affiliate/photo-link',{slug:b.dataset.slug});const url=(location.origin||'https://glowglps.com')+'/store-next/profile/'+encodeURIComponent(r.slug)+'#'+r.token;const target=document.querySelector('#photo-link-result');target.innerHTML=`<div class="notice"><strong>Private photo upload link</strong><input id="private-photo-link" type="text" readonly aria-label="Private photo upload link"><p>Share this link only with this affiliate. It expires in 30 days; creating a new link replaces their previous one.</p>${button('Copy private upload link','copy-photo-link','secondary')}</div>`;target.querySelector('input').value=url;target.scrollIntoView({behavior:'smooth',block:'center'})}
else if(action==='copy-photo-link'){await navigator.clipboard.writeText(document.querySelector('#private-photo-link').value);toast('Private photo upload link copied.')}
else if(action==='remove-profile-photo'){await profileApi('/photo',{remove:true});renderProfile(await profileApi(''));toast('Photo removed.')}
else if(['paid','cancel','shipped'].includes(action)){const status=action==='cancel'?'canceled':action;if(!confirm(action==='paid'?'Have you verified this exact payment in the receiving account?':action==='cancel'?'Cancel this order and release reserved stock?':'Mark this order shipped?'))return;await api('/api/admin/status',{id:b.dataset.id,status,verified:action==='paid',tracking:document.querySelector('#tracking')?.value||''});await loadAdmin();detail(b.dataset.id);toast(action==='paid'?'Payment saved. GoAffPro status appears below.':'Order updated.')}
}catch(err){toast(err.message)}finally{b.disabled=false}});
document.addEventListener('submit',async e=>{const f=e.target,formId=f.getAttribute('id');e.preventDefault();const submit=f.querySelector('[type=submit]');submit.disabled=true;const err=f.querySelector('.error');if(err)err.textContent='';try{const values=Object.fromEntries(new FormData(f));if(formId==='login'){await api('/api/admin/login',values);await loadAdmin()}
else if(formId==='staff-invite'){await api('/api/admin/staff/invite',values);await loadAdmin();toast('Invitation requested. Check Emails for delivery status.')}
else if(formId==='staff-reset'){const r=await api('/api/staff/reset',values);f.innerHTML=`<p role="status">${esc(r.message)}</p>`}
else if(formId==='staff-setup'){if(values.password!==values.confirm_password)throw new Error('Passwords must match.');await api('/api/staff/setup',{id:state.staffSetupId,token:state.staffSetupToken,password:values.password});state.staffSetupToken='';await loadAdmin()}
else if(formId==='email-test'){const r=await api('/api/admin/email/test',{...values,idempotency_key:f.dataset.key});await loadAdmin();toast(r.email?.message||'Test email requested.')}
else if(formId==='customer-forgot'){const r=await api('/api/account/forgot-password',values);f.innerHTML=`<p role="status">${esc(r.message)}</p>`}
else if(formId==='customer-register'){const r=await api('/api/account/register',values);f.innerHTML=`<p role="status">${esc(r.message)}</p>`}
else if(formId==='customer-login'){state.customer=await api('/api/account/login',values);renderAccount()}
else if(formId==='customer-setup'){if(values.password!==values.confirm_password)throw new Error('Passwords must match.');state.customer=await api('/api/account/setup',{customer_id:state.setupId,token:state.setupToken,password:values.password});state.setupToken='';history.replaceState(null,'','/store-next/account');renderAccount();toast('Your account is ready.')}
else if(formId==='rewards-import'){const file=f.elements.migration.files[0];if(!file||file.size>2*1024*1024)throw new Error('Choose the migration JSON file, up to 2 MB.');let data;try{data=JSON.parse(await file.text())}catch{throw new Error('Choose a valid JSON migration file.')}state.migrationPreview=await api('/api/admin/rewards/import-preview',{customers:data.customers});renderAdmin()}
else if(formId==='rewards-adjust'){await api('/api/admin/rewards/adjust',{...values,points:Number(values.points),idempotency_key:f.dataset.key});state.customerAdmin=await api('/api/admin/customers');renderAdmin();toast('Points adjustment recorded.')}
else if(formId==='checkout'){const customer={...values};delete customer.payment_method;const result=await api('/api/orders',{...cartData(),customer,payment_method:values.payment_method,idempotency_key:f.dataset.key});state.order=result.order;state.token=result.token;sessionStorage.removeItem('glow_cart');sessionStorage.setItem('glow_order',JSON.stringify({id:result.order.id,token:result.token}));renderOrder()}
else if(formId==='receipt'){const file=f.elements.screenshot.files[0];if(!file||file.size>3*1024*1024)throw new Error('Choose a screenshot under 3 MB.');const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});state.order=await api('/api/orders/'+state.order.id+'/receipt',{file:data,mime:file.type,reference:values.reference,phone:values.phone},state.token);renderOrder();toast('Order submitted with screenshot; awaiting payment review.')}
else if(formId==='affiliate-photo'){const file=f.elements.photo.files[0];if(!file||file.size>3*1024*1024)throw new Error('Choose a photo up to 3 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Could not read this photo.'));reader.readAsDataURL(file)});await profileApi('/photo',{file:data,mime:file.type});renderProfile(await profileApi(''));toast('Your storefront photo has been saved.')}
else if(formId==='product'){for(const k of ['price','stock','active'])values[k]=Number(values[k]);values.price=Math.round(values.price*100);if(values.id)values.id=Number(values.id);await api('/api/admin/product',values);await loadAdmin();toast('Product saved.')}
else if(formId==='coupon-form'){for(const k of ['value','minimum','max_uses','active'])values[k]=Number(values[k]);values.minimum=Math.round(values.minimum*100);if(values.kind==='fixed')values.value=Math.round(values.value*100);values.expires=values.expiry_date?Math.floor(new Date(values.expiry_date+'T23:59:59').getTime()/1000):0;await api('/api/admin/coupon',values);await loadAdmin();toast('Coupon saved.')}
else if(formId==='affiliate'){values.commission_bps=Number(values.commission_bps);values.active=Number(values.active);await api('/api/admin/affiliate',values);await loadAdmin();toast('Affiliate saved.')}
else if(formId==='shipstation-settings'){await api('/api/admin/shipstation/settings',{store_id:Number(values.store_id),enabled:values.enabled==='1'});await loadAdmin();toast('Shipping connection saved.')}
else if(formId==='checkout-settings'){await api('/api/admin/checkout-settings',values);await loadAdmin();toast('Checkout mode saved.')}
else if(formId==='settings'){await api('/api/admin/settings',{shipping_cents:Math.round(Number(values.shipping_cents)*100),free_shipping_cents:Math.round(Number(values.free_shipping_cents)*100),payment_links:Object.fromEntries(['venmo','paypal','cashapp','zelle'].map(k=>[k,values[k]]))});await loadAdmin();toast('Settings saved.')}
}catch(error){if(err)err.textContent=error.message;else toast(error.message)}finally{submit.disabled=false}});
function rewardsCart(){if(!state.customer)return `<p><a href="/store-next/account">Sign in to view your rewards</a></p>`;const w=state.customer.wallet;return `<div class="notice"><strong>${w.available} points available · ${money(w.value_cents)}</strong><p>1 point per $1 of products after discounts. 100 points = $5 off. Points work with one promo code and never expire.</p>${state.catalog.settings.demo?'<p>Test orders do not earn or spend real points.</p>':`<label>Points to use<input id="use-points" type="number" min="0" max="${w.available}" step="1" value="${state.points}"></label>${button('Apply points','apply-points','secondary')}`}</div>`}
function accountStoreUrl(){const slug=sessionStorage.getItem('glow_customer_store')||'';return /^[a-z0-9-]+$/.test(slug)?storeUrl(slug):'/store-next/'}
function ledgerTable(entries){return entries.length?`<div class="tablewrap"><table><thead><tr><th>Date</th><th>Activity</th><th>Points</th><th>Held change</th><th>Balance</th><th>Order / note</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${new Date(e.created*1000).toLocaleString()}</td><td>${esc(e.kind.replaceAll('_',' '))}</td><td>${e.points>0?'+':''}${e.points}</td><td>${e.reserved_delta>0?'+':''}${e.reserved_delta}</td><td>${e.balance_after}</td><td>${esc(e.order_id||e.note)}</td></tr>`).join('')}</tbody></table></div>`:'<p class="muted">No points transactions yet.</p>'}
async function loadAccount(){if(!state.catalog){state.catalog=await api('/api/catalog');renderMode(state.catalog.settings)}try{state.customer=await api('/api/account');renderAccount()}catch{state.customer=null;renderAccountLogin()}}
function renderAccountLogin(){app.innerHTML=`<div class="intro"><div class="eyebrow">Your Glow Lab account</div><h1>Your orders. Your rewards.</h1><p class="muted">Earn 1 point per $1 of products after discounts, excluding shipping and tax. 100 points = $5 off. Points never expire.</p></div><div class="split"><form id="customer-login" class="panel"><h2>Sign in</h2><label>Email<input name="email" type="email" autocomplete="username" required maxlength="150"></label><label>Password<input name="password" type="password" autocomplete="current-password" required maxlength="128"></label><button type="submit">Sign in</button><p class="error" role="alert"></p><p class="muted">${state.catalog?.settings.email_enabled?'Use the password reset form below.':'Forgot your password? Contact the store for a private reset link sent to your account email.'}</p></form><form id="customer-register" class="panel"><h2>Request an account</h2><label>Name<input name="name" autocomplete="name" required maxlength="150"></label><label>Email<input name="email" type="email" autocomplete="email" required maxlength="150"></label><button type="submit">Request account setup</button><p class="error" role="alert"></p><p class="muted">${state.catalog?.settings.email_enabled?'A private setup link will be emailed to you. Check your inbox and spam folder.':'Staff will provide a private setup link to your email. Automatic email delivery is not enabled yet.'} Use the same email as your previous orders to claim a migrated balance after verification.</p></form></div>${state.catalog?.settings.email_enabled?`<form id="customer-forgot" class="panel account-ledger"><h2>Reset your password</h2><label>Account email<input name="email" type="email" autocomplete="email" required maxlength="150"></label><button type="submit">Email password reset link</button><p class="error" role="alert"></p></form>`:''}<p><a href="${esc(accountStoreUrl())}">Back to the store</a></p>`}
function renderAccount(){const d=state.customer,w=d.wallet;app.innerHTML=`<div class="row"><div><div class="eyebrow">Your customer account</div><h1>Hi, ${esc(d.customer.name)}.</h1><p class="muted">${esc(d.customer.email)}</p></div>${button('Sign out','customer-logout','secondary')}</div><div class="metrics"><section class="panel metric"><strong>${w.available}</strong><small>Available points</small></section><section class="panel metric"><strong>${money(w.value_cents)}</strong><small>Available discount</small></section><section class="panel metric"><strong>${w.reserved}</strong><small>Points held for unpaid orders</small></section><section class="panel metric"><strong>${w.balance}</strong><small>Total points balance</small></section></div><div class="notice">Points never expire and can be used with one promo code. Earn 1 point for each whole $1 of products after all discounts, excluding shipping and tax. Each point is worth $0.05. Earned points appear after staff verify payment; test orders do not change your real balance.</div><section class="panel"><h2>Your orders</h2>${d.orders.map(o=>`<div class="row"><span>${esc(o.id)} · ${money(o.total)} · ${esc(orderLabel(o))}${o.is_test!==false?' · Test order':''}</span><button data-action="account-order" data-id="${esc(o.id)}" class="secondary">View order</button></div>`).join('')||'<p>No orders associated with this account yet.</p>'}<p class="muted">Earlier guest orders are not linked by email alone.</p></section><section class="panel account-ledger"><h2>Your points history</h2>${ledgerTable(d.ledger)}</section><p><a href="${esc(accountStoreUrl())}">Continue shopping</a></p>`}
function loadAccountSetup(){const parts=location.hash.slice(1).split('.');state.setupId=parts[0]||'';state.setupToken=parts[1]||'';history.replaceState(null,'',location.pathname);if(!/^[a-f0-9]{64}$/.test(state.setupId)||!/^[A-Za-z0-9_-]{43}$/.test(state.setupToken)){app.innerHTML='<h1>Account setup link unavailable</h1><p>Contact the store for a new private setup link.</p>';return}app.innerHTML=`<form id="customer-setup" class="panel login-panel"><div class="eyebrow">Private account setup</div><h1>Choose your password.</h1><p>Use a passphrase with 15–128 characters. Completing this private setup verifies the email account the link was sent to.</p><label>New password<input name="password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><label>Confirm password<input name="confirm_password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><button type="submit">Save password and sign in</button><p class="error" role="alert"></p><p class="muted">This link works once and expires after 24 hours. Reloading this page clears the link; reopen the original link if needed.</p></form>`}
function customersAdmin(){const d=state.customerAdmin,p=state.migrationPreview;if(!d)return '<p>Open Customers to load account and rewards records.</p>';return `<section class="panel"><h2>Customer accounts and rewards</h2><div class="notice">1 point per whole $1 of products after all discounts, excluding shipping and tax. Each point is worth $0.05. Points stack with one promo code and never expire. Membership levels are inactive.</div><p>${state.admin.email?.configured?'Use Email setup / reset to send a private link directly to the saved customer address.':'Automatic email delivery is not enabled. Create a private setup / reset link and email it only to the customer address shown.'} The customer chooses their password; completing setup claims any matching imported balance.</p><div id="customer-link-result" aria-live="polite"></div><div class="tablewrap"><table><thead><tr><th>Customer</th><th>Email</th><th>Status</th><th>Available points</th><th>Actions</th></tr></thead><tbody>${d.customers.map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.email)}</td><td>${a.verified?'Verified':'Awaiting email setup'}</td><td>${a.wallet.available} · ${money(a.wallet.value_cents)}</td><td><div class="actions">${state.admin.email?.configured?`<button data-action="send-customer-setup" data-id="${a.id}" class="secondary">Email setup / reset</button>`:''}<button data-action="customer-setup-link" data-id="${a.id}" class="secondary">${a.verified?'Password reset link':'Account setup link'}</button>${a.verified?`<button data-action="customer-ledger" data-id="${a.id}" class="secondary">Points history / adjustment</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>${!d.customers.length?'<p>No account requests yet. Customers can request setup at <a href="/store-next/account">the account page</a>.</p>':''}</section><div id="customer-ledger"></div><section class="panel account-ledger"><h2>Carry over WooCommerce balances</h2><p>Upload the saved migration JSON. Preview totals first, then import. Repeating the same file does not add points twice. Review changed source balances below before reconciling. Reconciliation carries over only the change since the previous WooCommerce snapshot and preserves new-store earnings and redemptions. Imported balances stay unclaimed until email setup is completed.</p><form id="rewards-import"><label>Migration JSON file · up to 2 MB<input name="migration" type="file" accept="application/json,.json" required></label><button type="submit">Preview balances</button><p class="error" role="alert"></p></form>${p?`<div class="notice"><strong>${p.count} rows · ${p.points_total} points · ${money(p.points_total*5)}</strong><p>${p.existing_count} already imported · ${p.held.length} held for email review · ${p.missing_redeem_history} missing historical redeemed value.</p>${p.held.map(r=>`<p>${esc(r.email)} — ${esc(r.reason)}</p>`).join('')}${p.conflicts.length?`<p><strong>Source changes to review: ${p.points_delta} points difference.</strong></p>${p.changes.map(r=>`<p>${esc(r.email)}: ${r.previous_points} → ${r.points} points (${r.delta>=0?'+':''}${r.delta})</p>`).join('')}${button('Reconcile these source balances','reconcile-rewards-import')}`:button('Import these balances','commit-rewards-import') }</div>`:''}<h3>${d.imports.length} imported balances</h3><p>${d.imports.filter(r=>r.claimed).length} claimed · ${d.imports.filter(r=>r.held).length} held for review</p><div class="tablewrap"><table><thead><tr><th>Email</th><th>Points</th><th>Redeemed history</th><th>Status</th></tr></thead><tbody>${d.imports.map(r=>`<tr><td>${esc(r.email)}</td><td>${r.points}</td><td>${r.redeem_points===null?'Missing':r.redeem_points}</td><td>${r.held?'Held for email review':r.claimed?'Claimed':'Awaiting verified account'}</td></tr>`).join('')}</tbody></table></div></section>`}
if(/\/store-next\/(account(?:-setup)?|profile\/[a-z0-9-]+)\/?$/.test(location.pathname))api('/api/catalog').then(d=>renderMode(d.settings)).catch(()=>{});
(/\/store-next\/account-setup\/?$/.test(location.pathname)?Promise.resolve(loadAccountSetup()):/\/store-next\/account\/?$/.test(location.pathname)?loadAccount():/\/store-next\/profile\/[a-z0-9-]+\/?$/.test(location.pathname)?loadProfile():/\/store-next\/admin\/?$/.test(location.pathname)?loadAdmin():loadStore()).catch(err=>{app.innerHTML=`<h1>Unable to load the store</h1><p class="error">${esc(err.message)}</p>`});

document.addEventListener('input',e=>{if(e.target.id==='order-search'){state.orderSearch=e.target.value;document.querySelector('#order-results').innerHTML=orderRows()}});
document.addEventListener('change',e=>{if(['order-status','order-mode'].includes(e.target.id)){state[e.target.id==='order-status'?'orderStatus':'orderMode']=e.target.value;document.querySelector('#order-results').innerHTML=orderRows()}});

function staffPanel(){return `<section class="panel"><h2>Staff access</h2><p>Each staff member has their own email and password, with full access to store operations. Only your owner login can invite staff or remove access.</p><form id="staff-invite"><div class="fields"><label>Name<input name="name" required maxlength="150"></label><label>Email<input name="email" type="email" required maxlength="150"></label></div><button type="submit">Send full-access invitation</button><p class="error" role="alert"></p></form><div class="tablewrap"><table><thead><tr><th>Name</th><th>Email</th><th>Status</th><th>Access</th><th>Action</th></tr></thead><tbody>${(state.admin.staff||[]).map(a=>`<tr><td>${esc(a.name)}</td><td>${esc(a.email)}</td><td>${!a.active?'Removed':a.verified?'Ready to sign in':'Awaiting password setup'}</td><td>${esc(a.access)}</td><td>${a.active?`<button class="danger" data-action="revoke-staff" data-id="${a.id}">Remove access</button>`:''}</td></tr>`).join('')}</tbody></table></div></section>`}
function loadStaffSetup(){const match=location.hash.match(/^#staff=([a-f0-9]{64})\.([A-Za-z0-9_-]{43})$/);history.replaceState(null,'',location.pathname);if(!match){app.innerHTML='<h1>Management setup link unavailable</h1>';return}state.staffSetupId=match[1];state.staffSetupToken=match[2];app.innerHTML=`<form id="staff-setup" class="panel login-panel"><div class="eyebrow">Private management setup</div><h1>Choose your management password.</h1><p>This gives you full store-management access. Use a passphrase with 15–128 characters.</p><label>New password<input name="password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><label>Confirm password<input name="confirm_password" type="password" autocomplete="new-password" minlength="15" maxlength="128" required></label><button type="submit">Save password and open management</button><p class="error" role="alert"></p></form>`}
